// public/sw.js
// This is the source file for VitePWA's injectManifest strategy.
// The plugin will automatically inject the precache manifest (self.__WB_MANIFEST)
// during the build process. Do not delete this file.
 
import { precacheAndRoute } from 'workbox-precaching';
 
// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST);
 
// Original custom push notification logic for Petopia Web Push
self.addEventListener('push', function(event) {
  const data = event.data ? event.data.json() : {};
  
  const options = {
    body: data.body || 'У вас новое уведомление',
    icon: '/images/Petopia.png',
    badge: '/images/Petopia.png',
    vibrate: [100, 50, 100],
    data: {
      dateOfArrival: Date.now(),
      primaryKey: 1
    }
  };
 
  event.waitUntil(
    self.registration.showNotification(data.title || 'Petopia', options)
  );
});
 
self.addEventListener('notificationclick', function(event) {
  event.notification.close();
  event.waitUntil(
    clients.openWindow('/dashboard')
  );
});